import { Component, ComponentInterface, Element, Event, EventEmitter, h, Host, Prop, Watch } from '@stencil/core';
import { CLOSE_BUTTON_LABEL } from '../../a11y';
import { FileUploadStatus } from '../../types';
import { FocusHelper } from '../../utils/focus-helper';

/**
 * @slot default - The default slot for the name of the file
 */
@Component({
  tag: 'groupui-upload-status',
  styleUrl: 'upload-status.scss',
  shadow: true,
})
export class UploadStatus implements ComponentInterface {
  /**
   * size of the file
   */
  @Prop({ reflect: true }) readonly fileSize: string;

  /**
   * description, e.g. 'Pending', 'Success Message', 'Error Message'
   */
  @Prop({ reflect: true }) readonly message: string;

  /**
   * status of the file upload status
   */
  @Prop({ reflect: true }) readonly status: FileUploadStatus;

  /**
   * sets the file upload status size
   */
  @Prop({ reflect: true }) readonly size: 's' | 'l';

  /**
   * toggles visibility
   */
  @Prop({ reflect: true, mutable: true }) visible: boolean = false;

  /**
   * sets a custom accessible text for the close button
   */
  @Prop({ reflect: true, attribute: 'a11y-label-close-button' }) readonly a11yLabelCloseButton: string;

  /**
   * Is dispatched when the file upload status is closed.
   */
  @Event({ bubbles: false }) groupuiClose: EventEmitter<void>;

  /**
   * Dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @Element() host: HTMLElement;

  @Watch('visible')
  watchVisible() {
    if (!this.visible) {
      this.groupuiClose.emit();
    }
  }

  private onCloseClick = () => {
    this.visible = false;
    const previousFocusableElement = FocusHelper.getPreviousFocusableElement(this.host);
    previousFocusableElement && previousFocusableElement.focus && previousFocusableElement.focus();
  };

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  private getIndicator() {
    switch (this.status) {
      case 'uploading':
        return <groupui-loading embedded size="s"></groupui-loading>;
      case 'error':
      case 'success':
        return <groupui-icon name={`${this.status}-filled-16`}></groupui-icon>;
      default:
        return null;
    }
  }

  private ariaLabel(): string {
    return this.host.innerHTML?.trim();
  }

  render() {
    return (
      <Host>
        <div id="wrapper" role="status" aria-label={this.ariaLabel()} aria-description={this.message} tabindex={0}>
          <div id="title" aria-hidden="true">
            <slot></slot>
          </div>
          <div id="status" aria-hidden="true">
            {this.fileSize && <div id="file-size">{this.fileSize}</div>}
            {this.message && (
              <div id="state">
                {this.getIndicator()}
                {this.message}
              </div>
            )}
          </div>
          <groupui-icon-button
            icon="close-16"
            onClick={this.onCloseClick}
            aria-label={this.a11yLabelCloseButton || CLOSE_BUTTON_LABEL}
          ></groupui-icon-button>
        </div>
      </Host>
    );
  }
}
